import{_ as s,o as r,c as e,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Crimson/Seastar OSD Meeting 2018-12-18","description":"","frontmatter":{"title":"Crimson/Seastar OSD Meeting 2018-12-18","date":"2018-12-18T00:00:00.000Z","updated":"2018-12-20T00:00:00.000Z","tags":["Ceph","Crimson 项目","Messenger","OSD","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Crimson_Seastar_OSD_Meeting_2018-12-18.md","filePath":"posts/2018/Crimson_Seastar_OSD_Meeting_2018-12-18.md","lastUpdated":1780460162000}'),n={name:"posts/2018/Crimson_Seastar_OSD_Meeting_2018-12-18.md"};function t(o,i,a,g,m,p){return r(),e("div",null,[...i[0]||(i[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年12月18日 <strong>会议地点</strong>： 未知 <strong>参会人员</strong>： 多位（具体姓名未提及） <strong>会议主题</strong>： Ceph 项目进展讨论，特别是 crimson 项目和 messenger 的开发</p><p><strong>关键细节</strong>：</p><ul><li><strong>Crimson 项目</strong>： <ul><li>讨论了 crimson 项目的进展，包括与 existing CI 集成、性能提升和人员投入。</li><li>决定从零开始重新设计 crimson 项目，以更好地利用 sister 和提高性能。</li><li>讨论了 crimson 项目与现有 Ceph 代码库的兼容性，并决定在 crimson 项目中实现新的功能。</li></ul></li><li><strong>messenger</strong>： <ul><li>讨论了 messenger 的性能和稳定性，并决定进行性能测试。</li><li>讨论了 buffer list 的实现，并决定对其进行优化以提高性能。</li><li>讨论了 crimson 项目中 messenger 的集成，并决定在 crimson 项目中实现新的功能。</li></ul></li><li><strong>其他</strong>： <ul><li>讨论了 OSD 的 sharding 和 dispatcher 的实现。</li><li>讨论了 crimson 项目中与 monitor 和 OSD 的集成。</li></ul></li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>Crimson 项目的重新设计</li><li>messenger 的性能和稳定性</li><li>buffer list 的实现</li><li>OSD 的 sharding</li><li>dispatcher 的实现</li></ul><p><strong>决定的事项</strong>：</p><ul><li>从零开始重新设计 crimson 项目</li><li>对 messenger 进行性能测试</li><li>对 buffer list 进行优化</li><li>在 crimson 项目中实现新的功能</li><li>在 crimson 项目中集成 messenger</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>重新设计 crimson 项目</li><li>进行 messenger 的性能测试</li><li>对 buffer list 进行优化</li><li>在 crimson 项目中实现新的功能</li><li>在 crimson 项目中集成 messenger</li><li>继续讨论 OSD 的 sharding 和 dispatcher 的实现</li></ul><p><strong>其他</strong>：</p><ul><li>讨论了 crimson 项目的资源分配问题。</li><li>讨论了 crimson 项目的长期发展。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了多个英文关键词，如 crimson、messenger、OST、PG、sharding、dispatcher 等。</li><li>会议中提到了多个代码库，如 crimson、messenger、sister 等。</li></ul><p><strong>改进点</strong>：</p><ul><li>确保了会议纪要中包含了所有关键细节，包括 crimson 项目和 messenger 的开发进展。</li><li>更准确地反映了会议中讨论的主要议题和决定的事项。</li><li>强调了后续行动计划，确保了会议的成果能够得到有效执行。</li><li>保留了计算机科学/ceph相关领域的英文原文关键词，以便于专业人士理解和交流。</li></ul>',16)])])}const u=s(n,[["render",t]]);export{_ as __pageData,u as default};
